package cn.sixnine.filmlog;

import android.app.*;
import android.content.Intent;
import android.graphics.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;

public final class StockDetailActivity extends WorkspaceActivity {
    private int cover,scrollY;private ScrollView scroll;private JSONArray covers;private ImageView image;private FilmStockStore.Stock stock;
    private int dp(int n){return LibraryUi.dp(this,n);}
    private TextView text(String value,int size,int color){return LibraryUi.text(this,value,size,color);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);try(LogStore logs=new LogStore(this)){FilmStockStore store=new FilmStockStore(logs);String id=getIntent().getStringExtra("stock");stock=id!=null&&(id.startsWith("original:")||id.startsWith("filmer:"))?FilmStockStore.builtin(this,id):store.get(id);}catch(Exception missing){finish();return;}if(saved!=null){cover=saved.getInt("cover");scrollY=saved.getInt("scroll");}render();}
    private void render(){
        LinearLayout root=LibraryUi.column(this);root.setBackgroundColor(getColor(R.color.ui_background));setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
        root.addView(LibraryUi.header(this,"胶片资料",this::finish,stock.builtin?null:LibraryUi.icon(this,0xe1fe,"更多操作",this::actions)));
        FrameLayout viewport=new FrameLayout(this);viewport.setTag("stock-detail-viewport");root.addView(viewport,new LinearLayout.LayoutParams(-1,0,1));Bitmap brand=FilmDetails.themedLogo(this,stock.id);boolean themed=brand!=null;if(!themed)brand=FilmDetails.logo(this,stock.id);if(brand!=null){ImageView watermark=new ImageView(this);watermark.setTag("film-brand-watermark");watermark.setImageBitmap(brand);watermark.setScaleType(ImageView.ScaleType.FIT_CENTER);watermark.setAlpha(.05f);watermark.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);if(night()&&!themed)watermark.setColorFilter(getColor(R.color.ui_ink),PorterDuff.Mode.SRC_IN);FrameLayout.LayoutParams size=new FrameLayout.LayoutParams(-1,dp(72),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);size.leftMargin=size.rightMargin=dp(32);size.bottomMargin=dp(28);viewport.addView(watermark,size);}
        scroll=new ScrollView(this);scroll.setTag("stock-detail-scroll");scroll.setFillViewport(false);scroll.setVerticalScrollBarEnabled(false);LinearLayout body=LibraryUi.column(this);body.setPadding(dp(16),0,dp(16),dp(24));scroll.addView(body);viewport.addView(scroll,new FrameLayout.LayoutParams(-1,-1));
        covers=FilmArtwork.covers(this,stock.id,getIntent().getStringExtra("format"));LinearLayout hero=new LinearLayout(this);hero.setGravity(Gravity.CENTER_VERTICAL);hero.setPadding(0,dp(18),0,dp(22));image=new ImageView(this);image.setTag("stock-cover");image.setScaleType(ImageView.ScaleType.FIT_CENTER);hero.addView(image,new LinearLayout.LayoutParams(dp(112),dp(112)));LinearLayout identity=LibraryUi.column(this);TextView b=text(stock.brand,14,getColor(R.color.ui_muted));b.setTag("stock-brand");identity.addView(b);TextView model=text(FilmDetails.model(stock),30,getColor(R.color.ui_ink));model.setTypeface(Typeface.DEFAULT,Typeface.BOLD);model.setTag("stock-model");LinearLayout.LayoutParams modelSize=new LinearLayout.LayoutParams(-1,-2);modelSize.topMargin=dp(6);identity.addView(model,modelSize);LinearLayout.LayoutParams words=new LinearLayout.LayoutParams(0,-2,1);words.leftMargin=dp(18);hero.addView(identity,words);body.addView(hero);showCover();image.setOnClickListener(v->gallery());final float[] down={0,0};image.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){down[0]=e.getX();down[1]=e.getY();return true;}if(e.getAction()==MotionEvent.ACTION_UP){float dx=e.getX()-down[0],dy=e.getY()-down[1];if(Math.abs(dx)>dp(40)&&Math.abs(dx)>Math.abs(dy)){cover=Math.max(0,Math.min(covers.length()-1,cover+(dx<0?1:-1)));showCover();}else v.performClick();return true;}return true;});
        LinearLayout facts=LibraryUi.column(this);facts.setTag("stock-facts");LinearLayout.LayoutParams inset=new LinearLayout.LayoutParams(-1,-2);inset.leftMargin=inset.rightMargin=dp(16);body.addView(facts,inset);LibraryUi.fact(this,facts,"可用规格",stock.formats.isEmpty()?"未填写":stock.formats);LibraryUi.fact(this,facts,"冲洗工艺",stock.process.isEmpty()?"未填写":stock.process);LibraryUi.fact(this,facts,"感光度",FilmStockStore.isoText(stock));LibraryUi.fact(this,facts,"是否在产",FilmDetails.production(this,stock.id));LibraryUi.fact(this,facts,"类型",FilmDetails.type(this,stock.id));
        JSONObject art=FilmArtwork.get(this,stock.id);String description=art==null?"":art.optString("description");if(!description.isEmpty()){TextView intro=text(description,15,getColor(R.color.ui_ink));intro.setTag("stock-description");intro.setJustificationMode(android.text.Layout.JUSTIFICATION_MODE_INTER_WORD);intro.setLineSpacing(android.util.TypedValue.applyDimension(android.util.TypedValue.COMPLEX_UNIT_SP,27.75f,getResources().getDisplayMetrics())-intro.getPaint().getFontMetricsInt(null),1f);LinearLayout.LayoutParams paragraph=new LinearLayout.LayoutParams(-1,-2);paragraph.leftMargin=paragraph.rightMargin=dp(16);paragraph.topMargin=dp(22);body.addView(intro,paragraph);}
        if(getIntent().getBooleanExtra("select",false)){Button choose=LibraryUi.action(this,"选择这款胶片",true,()->{setResult(RESULT_OK,new Intent().putExtra("stock",stock.id));finish();});LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(-1,-2);size.setMargins(dp(16),dp(10),dp(16),dp(16));root.addView(choose,size);}scroll.post(()->scroll.scrollTo(0,scrollY));
    }
    private boolean night(){return (getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;}
    private void actions(){new AlertDialog.Builder(this).setTitle(stock.title()).setItems(new String[]{"编辑片种资料",stock.archived?"恢复片种":"归档片种"},(d,w)->{if(w==0){setResult(RESULT_OK,new Intent().putExtra("edit_stock",stock.id));finish();}else try(LogStore logs=new LogStore(this)){new FilmStockStore(logs).archive(stock.id,!stock.archived);setResult(RESULT_OK,new Intent().putExtra("refresh_stocks",true));finish();}}).show();}
    private void showCover(){if(covers==null||covers.length()==0){image.setImageDrawable(null);image.setContentDescription("暂无封面");return;}cover=Math.max(0,Math.min(cover,covers.length()-1));JSONObject item=covers.optJSONObject(cover);image.setImageBitmap(FilmArtwork.image(this,item.optString("image")));image.setContentDescription(stock.title()+"封面，点击查看，第"+(cover+1)+"张，共"+covers.length()+"张");}
    private void gallery(){if(covers.length()==0)return;LinearLayout content=LibraryUi.column(this);content.setPadding(dp(16),0,dp(16),dp(16));ImageView full=new ImageView(this);full.setScaleType(ImageView.ScaleType.FIT_CENTER);content.addView(full,new LinearLayout.LayoutParams(-1,dp(280)));TextView label=text("",13,getColor(R.color.ui_muted));label.setGravity(Gravity.CENTER);content.addView(label);Runnable update=()->{JSONObject item=covers.optJSONObject(cover);full.setImageBitmap(FilmArtwork.image(this,item.optString("image")));label.setText((cover+1)+" / "+covers.length());showCover();};if(covers.length()>1){LinearLayout controls=new LinearLayout(this);controls.addView(LibraryUi.action(this,"上一张",false,()->{cover=Math.max(0,cover-1);update.run();}),new LinearLayout.LayoutParams(0,-2,1));controls.addView(LibraryUi.action(this,"下一张",false,()->{cover=Math.min(covers.length()-1,cover+1);update.run();}),new LinearLayout.LayoutParams(0,-2,1));content.addView(controls);}update.run();LibraryUi.sheet(this,"封面",content,null);}
    @Override protected void onSaveInstanceState(Bundle out){out.putInt("cover",cover);out.putInt("scroll",scroll==null?0:scroll.getScrollY());super.onSaveInstanceState(out);}
}
